"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["78007"],{56708(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca_requerida.categoria_repetida_nos_candidatos_atendidos","status":422,"titulo":"A banca repete uma categoria de documento nos candidatos atendidos"},"descricao":{"codigo":"uniplus.selecao.banca_requerida.categoria_repetida_nos_candidatos_atendidos","requisitos":["UNI-REQ-0470"],"oQueAconteceu":["Uma banca da fase cita a mesma categoria de documento duas ou mais vezes nos\\ncandidatos atendidos.","Os candidatos atendidos s\xe3o o conjunto de categorias que aquela banca julga\\n(UNI-REQ-0470). Repetir uma categoria n\xe3o acrescenta nada e deixa a declara\xe7\xe3o\\namb\xedgua entre engano de digita\xe7\xe3o e inten\xe7\xe3o de dizer outra coisa. Como o\\nconjunto vai congelado na configura\xe7\xe3o publicada e responde pelo parecer e pelo\\nrecurso do certame inteiro, a repeti\xe7\xe3o \xe9 recusada na origem.","A recusa vale para qualquer banca da fase, tenha ela outras bancas do mesmo tipo\\nou n\xe3o. A mensagem cita a fase pelo c\xf3digo e a banca pelo nome do tipo e pelo\\nn\xfamero dela, e o campo apontado \xe9 `fases[i].bancasRequeridas[p].categoriasDocumentoIds[k]`.\\nNa grava\xe7\xe3o a recusa vem na lista `errors[]`."],"comoResolver":["Remova a repeti\xe7\xe3o. Se a inten\xe7\xe3o era dar \xe0 banca compet\xeancia sobre mais de uma\\nmat\xe9ria, declare categorias distintas, uma para cada. Se era corrigir a categoria,\\ntroque-a em vez de acrescentar a nova ao lado da anterior.","Havendo outra banca do mesmo tipo, a regra dos\\n[candidatos atendidos](/erros/uniplus.selecao.banca_requerida.candidatos_atendidos_obrigatorios)\\ncontinua valendo depois da corre\xe7\xe3o.","O painel de conformidade do processo mostra o resultado no item\\n`cronograma_candidatos_atendidos_das_bancas`."],"ondeAparece":["- Defini\xe7\xe3o do cronograma de fases do processo seletivo\\n- Leitura do documento de configura\xe7\xe3o do processo seletivo\\n- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca requerida"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);